package com.codepilot1c.core.search;
import static org.junit.Assert.*;
import org.junit.Test;
import java.nio.file.*;
import java.nio.file.attribute.FileTime;
import java.util.*;
import java.util.concurrent.*;

public class ProjectBm25IndexTest {
    static class Fixture implements AutoCloseable {
        final Path root;Fixture()throws Exception{root=Files.createTempDirectory("bm25-test-");}
        Path put(String rel,String text)throws Exception{Path p=root.resolve(rel);Files.createDirectories(p.getParent());Files.writeString(p,text);return p;}
        ProjectBm25Index index(){return new ProjectBm25Index(root);}
        public void close()throws Exception{for(int attempt=0;attempt<5;attempt++){try(var files=Files.walk(root)){for(Path p:files.sorted(Comparator.reverseOrder()).toList())Files.deleteIfExists(p);return;}catch(java.nio.file.DirectoryNotEmptyException e){if(attempt==4)throw e;Thread.sleep(25);}}}
    }
    static String code(String name,String body){return "Процедура "+name+"()\n"+body+"\nКонецПроцедуры\n";}
    @SuppressWarnings("unchecked")static List<Map<String,Object>> rows(Map<String,Object> result){return (List<Map<String,Object>>)result.get("results");}
    @SuppressWarnings("unchecked")static Map<String,Object> meta(Map<String,Object> result){return (Map<String,Object>)result.get("index");}
    @Test public void unicodeCamelCaseAndLightRussianInflections(){var terms=Bm25Documents.tokens("ПроверитьДоступностьСклада Ёлка snake_case",30);assertTrue(terms.contains("склад"));assertTrue(terms.contains("доступност"));assertTrue(terms.contains("snake"));assertEquals(Bm25Documents.normalize("Склада"),Bm25Documents.normalize("Склад"));assertEquals(Bm25Documents.normalize("Ёлка"),Bm25Documents.normalize("Елка"));}
    @Test public void methodsHaveAccurateRangesAndIgnoreQuotedDeclarations(){String s="// header\nПроцедура Настоящая()\nТекст = \"text\nПроцедура Ложная()\nКонецПроцедуры\n|end\";\nКонецПроцедуры\n";var chunks=Bm25Documents.chunks(s);assertEquals(1,chunks.size());assertEquals("Настоящая",chunks.get(0).method());assertEquals(2,chunks.get(0).declaration());assertEquals(7,chunks.get(0).end());}
    @Test public void englishMethodsAndCommentedKeywords(){var chunks=Bm25Documents.chunks("// Function Fake()\nProcedure Real()\n// EndProcedure\nEndProcedure\n");assertEquals(1,chunks.size());assertEquals("Real",chunks.get(0).method());assertEquals(4,chunks.get(0).end());}
    @Test public void ranksMethodsAndReturnsBoundedEvidence()throws Exception{try(var f=new Fixture()){f.put("src/CommonModules/Storage/Module.bsl",code("ПроверитьДоступностьСклада","// проверка доступности склада\nРезультат = Истина;")+code("Другая","// склад"));var r=f.index().search("доступность склада","modules",5,false);assertEquals("ПроверитьДоступностьСклада",rows(r).get(0).get("method"));assertEquals("src/CommonModules/Storage/Module.bsl",rows(r).get(0).get("file_path"));assertEquals("sha256",meta(r).get("returned_files_verification"));assertTrue(((String)rows(r).get(0).get("snippet")).length()<=1200);}}
    @Test public void exactIdentifierAndStableTieOrder()throws Exception{try(var f=new Fixture()){f.put("src/CommonModules/B/Module.bsl",code("UniqueMethod","// stock"));f.put("src/CommonModules/A/Module.bsl",code("UniqueMethod","// stock"));var r=f.index().search("UniqueMethod","modules",1,false);assertTrue(((String)rows(r).get(0).get("file_path")).contains("/A/"));assertEquals(true,r.get("has_more"));assertEquals(2,r.get("total_results"));}}
    @Test public void onlyChangedFilesAreReadOnWarmUpdate()throws Exception{try(var f=new Fixture()){f.put("src/CommonModules/A/Module.bsl",code("One","// apple"));f.put("src/CommonModules/B/Module.bsl",code("Two","// orange"));var index=f.index();index.search("apple","modules",5,false);assertEquals(0,meta(index.search("apple","modules",5,false)).get("updated_files"));f.put("src/CommonModules/B/Module.bsl",code("Two","// banana updated"));var r=index.search("banana","modules",5,false);assertEquals(1,meta(r).get("updated_files"));assertEquals("Two",rows(r).get(0).get("method"));}}
    @Test public void deletionAndRenameRemoveOldDocuments()throws Exception{try(var f=new Fixture()){var p=f.put("src/CommonModules/A/Module.bsl",code("OldName","// apple"));var index=f.index();index.search("apple","modules",5,false);Files.delete(p);f.put("src/CommonModules/B/Module.bsl",code("NewName","// apple"));var r=index.search("apple","modules",5,false);assertEquals(1,rows(r).size());assertEquals("NewName",rows(r).get(0).get("method"));}}
    @Test public void metadataSynonymInvalidatesDependentModule()throws Exception{try(var f=new Fixture()){f.put("src/Catalogs/Locations/Locations.mdo","<Object><synonym><value>Янтарь</value></synonym></Object>");f.put("src/Catalogs/Locations/Module.bsl",code("Open","Возврат;"));var index=f.index();assertEquals(1,rows(index.search("Янтарь","modules",5,false)).size());f.put("src/Catalogs/Locations/Locations.mdo","<Object><synonym><value>Берилл</value></synonym></Object>");assertEquals(0,rows(index.search("Янтарь","modules",5,false)).size());assertEquals(1,rows(index.search("Берилл","modules",5,false)).size());}}
    @Test public void branchSwitchForcesRefreshEvenWithSameFileStamp()throws Exception{try(var f=new Fixture()){f.put(".git/HEAD","ref: refs/heads/one\n");f.put(".git/refs/heads/one","111\n");var p=f.put("src/CommonModules/A/Module.bsl",code("Name","// apple"));var index=f.index();index.search("apple","modules",5,false);FileTime time=Files.getLastModifiedTime(p);f.put("src/CommonModules/A/Module.bsl",code("Name","// grape"));Files.setLastModifiedTime(p,time);f.put(".git/HEAD","ref: refs/heads/two\n");f.put(".git/refs/heads/two","222\n");var r=index.search("grape","modules",5,false);assertEquals(1,rows(r).size());assertEquals(1,meta(r).get("updated_files"));}}
    @Test public void changedReturnedFileHashAutomaticallyRebuildsOnce()throws Exception{try(var f=new Fixture()){var p=f.put("src/CommonModules/A/Module.bsl",code("Name","// apple"));var index=f.index();index.search("apple","modules",5,false);FileTime t=Files.getLastModifiedTime(p);f.put("src/CommonModules/A/Module.bsl",code("Name","// grape"));Files.setLastModifiedTime(p,t);var r=index.search("apple","modules",5,false);assertEquals(0,rows(r).size());assertEquals(true,r.get("retried_source_change"));assertEquals(1,rows(index.search("grape","modules",5,false)).size());}}
    @Test public void hiddenFoldersAndNonSourceArtifactsAreExcluded()throws Exception{try(var f=new Fixture()){f.put("src/CommonModules/A/Module.bsl",code("Visible","// visible"));f.put("src/.hidden/Module.bsl",code("Private","// hiddenneedle"));f.put("src/Templates/private.txt","hiddenneedle");var r=f.index().search("hiddenneedle","all",5,false);assertTrue(rows(r).isEmpty());assertEquals(1,meta(r).get("files"));}}
    @Test public void scopeAndUppercaseExtensionsAreRespected()throws Exception{try(var f=new Fixture()){f.put("src/CommonModules/A/Module.BSL",code("Find","// uniquequery"));f.put("src/Queries/read.SDBL","ВЫБРАТЬ uniquequery");var index=f.index();assertEquals(1,rows(index.search("uniquequery","modules",5,false)).size());assertEquals(1,rows(index.search("uniquequery","queries",5,false)).size());assertEquals(2,rows(index.search("uniquequery","all",5,false)).size());}}
    @Test public void tooLargeFilesAreExplicitlyPartial()throws Exception{try(var f=new Fixture()){f.put("src/CommonModules/A/Module.bsl",code("Find","// visible"));Path large=f.put("src/CommonModules/A/Huge.bsl","");try(var file=new java.io.RandomAccessFile(large.toFile(),"rw")){file.setLength(8L*1024*1024+1);}var r=f.index().search("visible","modules",5,false);assertEquals(true,meta(r).get("partial"));assertEquals(1,meta(r).get("skipped_files"));}}
    @Test public void invalidQueriesRejectBeforeIndexWork()throws Exception{try(var f=new Fixture()){var index=f.index();for(String query:List.of("","и в на","x".repeat(1001)))assertThrows(IllegalArgumentException.class,()->index.search(query,"all",5,false));assertThrows(IllegalArgumentException.class,()->index.search("valid","bad",5,false));assertThrows(IllegalArgumentException.class,()->index.search("valid","all",21,false));}}
    @Test public void concurrentQueriesShareAConsistentIndex()throws Exception{try(var f=new Fixture()){f.put("src/CommonModules/A/Module.bsl",code("Find","// visible"));var index=f.index();ExecutorService pool=Executors.newFixedThreadPool(3);try{List<Future<Map<String,Object>>> futures=new ArrayList<>();for(int i=0;i<8;i++)futures.add(pool.submit(()->index.search("visible","modules",5,false)));for(var future:futures)assertEquals(1,rows(future.get()).size());}finally{pool.shutdownNow();}}}
    @Test public void bomDoesNotChangeCitationLines()throws Exception{try(var f=new Fixture()){f.put("src/CommonModules/A/Module.bsl","\ufeff"+code("Find","// visible"));assertEquals(1,rows(f.index().search("visible","modules",5,false)).get(0).get("line"));}}
    @Test public void sourceQuotaFailsInsteadOfReportingAnEmptySuccess()throws Exception{try(var f=new Fixture()){for(int i=0;i<33;i++){Path p=f.put("src/CommonModules/A/M"+i+".bsl","");try(var file=new java.io.RandomAccessFile(p.toFile(),"rw")){file.setLength(8L*1024*1024);}}assertThrows(java.io.IOException.class,()->f.index().search("valid","all",5,false));}}

    @Test public void explicitRebuildDropsDeadVocabulary()throws Exception{try(var f=new Fixture()){f.put("src/CommonModules/A/Module.bsl",code("Name","// alphatoken betatoken gammatoken"));var index=f.index();index.search("alphatoken","modules",5,false);f.put("src/CommonModules/A/Module.bsl",code("Name","// deltatoken"));var rebuilt=index.search("deltatoken","modules",5,true);var fresh=f.index().search("deltatoken","modules",5,false);assertEquals(meta(fresh).get("terms"),meta(rebuilt).get("terms"));}}
    @Test public void gitFileAndCommonDirDoNotForceEveryWarmQuery()throws Exception{try(var f=new Fixture()){f.put(".git","gitdir: .gitdata/worktrees/one\n");f.put(".gitdata/worktrees/one/HEAD","ref: refs/heads/topic\n");f.put(".gitdata/worktrees/one/commondir","../..\n");f.put(".gitdata/refs/heads/topic","111\n");f.put("src/CommonModules/A/Module.bsl",code("Name","// apple"));var index=f.index();var first=index.search("apple","modules",5,false);assertNotEquals("unavailable",meta(first).get("branch_context"));assertEquals(0,meta(index.search("apple","modules",5,false)).get("updated_files"));f.put(".gitdata/refs/heads/topic","222\n");assertEquals(1,meta(index.search("apple","modules",5,false)).get("updated_files"));}}

    @Test public void malformedLongMethodNamesCannotEscapeOutputLimits()throws Exception{try(var f=new Fixture()){f.put("src/CommonModules/A/Module.bsl",code("A".repeat(20000),"// needle"));var r=f.index().search("needle","modules",5,false);assertEquals(256,((String)rows(r).get(0).get("method")).length());assertEquals(true,rows(r).get(0).get("method_name_truncated"));assertEquals(true,meta(r).get("partial"));}}
}
